draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';

  // bird
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30, 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 10);
  ctx.lineTo(W/2 - 40, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 10);
  ctx.lineTo(W/2 + 40, H/2 + 30);
  ctx.stroke();

  // wings
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 - 10);
  ctx.lineTo(W/2 - 40 - 20*Math.sin(t), H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 - 10);
  ctx.lineTo(W/2 + 40 + 20*Math.sin(t), H/2 - 30);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 + 40);
  ctx.lineTo(W/2 - 10 + 10*Math.cos(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 + 40);
  ctx.lineTo(W/2 + 10 - 10*Math.cos(t), H/2 + 60);
  ctx.stroke();

  ctx.restore();
}
